const localStorage2 = {
    namespace: '',
    setNamespace(ns) {
        this.namespace = ns ? ns + ':' : '';
    },
    set(key, value, options = {}) {
        const { expires, raw } = options;
        const data = {
            value: raw ? value : JSON.stringify(value),
            expires: expires ? Date.now() + expires : null,
            raw: !!raw
        };
        localStorage.setItem(this.namespace + key, JSON.stringify(data));
    },
    get(key, defaultValue = null) {
        const data = localStorage.getItem(this.namespace + key);
        if (!data) return defaultValue;
        try {
            const { value, expires, raw } = JSON.parse(data);
            if (expires && Date.now() > expires) {
                this.remove(key);
                return defaultValue;
            }
            return raw ? value : JSON.parse(value);
        } catch {
            return defaultValue;
        }
    },
    remove(key) {
        localStorage.removeItem(this.namespace + key);
    },
    clear(namespacesOnly = false) {
        if (!namespacesOnly) {
            localStorage.clear();
            return;
        }
        if (this.namespace) {
            for (let i = localStorage.length - 1; i >= 0; i--) {
                const key = localStorage.key(i);
                if (key.startsWith(this.namespace)) {
                    localStorage.removeItem(key);
                }
            }
        }
    }
}

