function debounceAnimation(callback) {
    let frameId = null;
    return (...args) => {
        if (frameId) {
            cancelAnimationFrame(frameId);
        }
        frameId = requestAnimationFrame(() => {
            callback(...args);
            frameId = null;
        });
        return () => {
            if (frameId) {
                cancelAnimationFrame(frameId);
                frameId = null;
            }
        };
    };
}

function observeDOMChanges(target, callback, options = {}) {
    const defaultOptions = {
        attributes: true,
        childList: true,
        subtree: true
    };
    const opts = { ...defaultOptions, ...options };
    const observer = new MutationObserver(callback);
    observer.observe(target, opts);
    return () => observer.disconnect();
}

