  } catch {
    return null;
  } finally {
    clearTimeout(t);
  }
}

// adj: Array of adjacency lists, each item is [to, weight]
function dijkstra(n, adj, src){
  const INF = Number.MAX_SAFE_INTEGER;
  const dist = Array(n).fill(INF); dist[src]=0;
  // binary heap priority queue of [dist, node]
  const heap = [];
  const push = (item)=>{ heap.push(item); siftUp(heap.length-1); };
  const pop = ()=>{ if(heap.length===0) return null; const top=heap[0]; const x=heap.pop(); if(heap.length){ heap[0]=x; siftDown(0);} return top; };
  const siftUp = (i)=>{ while(i>0){ const p=(i-1)>>1; if(heap[p][0] <= heap[i][0]) break; [heap[p],heap[i]]=[heap[i],heap[p]]; i=p; } };
  const siftDown = (i)=>{ const n=heap.length; while(true){ let l=i*2+1, r=l+1, s=i; if(l<n && heap[l][0]<heap[s][0]) s=l; if(r<n && heap[r][0]<heap[s][0]) s=r; if(s===i) break; [heap[i],heap[s]]=[heap[s],heap[i]]; i=s; } };
  push([0, src]);
  while(heap.length){
    const [d,u]=pop();
    if(d!==dist[u]) continue;
    for(const [v,w] of adj[u]){ const nd=d+w; if(nd<dist[v]){ dist[v]=nd; push([nd,v]); } }
  }
  return dist;
}

