function kruskalMST(n, edges){
  edges = edges.slice().sort((a,b)=>a[2]-b[2]);
  const p = Array(n).fill(0).map((_,i)=>i);
  const r = Array(n).fill(0);
  const find = x => p[x]===x?x:(p[x]=find(p[x]));
  const unite = (a,b)=>{ a=find(a); b=find(b); if(a===b) return false; if(r[a]<r[b]) [a,b]=[b,a]; p[b]=a; if(r[a]===r[b]) r[a]++; return true; };
  let total=0,cnt=0;
  for(const [u,v,w] of edges){ if(unite(u,v)){ total+=w; if(++cnt===n-1) break; } }
  return cnt===n-1? total: -1;
}

// edges: [u,v,w]
function bellmanFord(n, edges, src){
  const INF = Number.MAX_SAFE_INTEGER;
  const dist = Array(n).fill(INF); dist[src]=0;
  for(let i=1;i<=n-1;i++){
    let updated=false;
    for(const [u,v,w] of edges){ if(dist[u]!==INF && dist[u]+w<dist[v]){ dist[v]=dist[u]+w; updated=true; } }
    if(!updated) break;
  }
  for(const [u,v,w] of edges){ if(dist[u]!==INF && dist[u]+w<dist[v]) return [dist, true]; }
  return [dist, false];
}

function topoSortKahn(n, adj){
  const indeg = Array(n).fill(0);
  for(let u=0;u<n;u++) for(const v of adj[u]) indeg[v]++;
  const q=[]; for(let i=0;i<n;i++) if(indeg[i]===0) q.push(i);
  const order=[];
  for(let h=0; h<q.length; h++){ const u=q[h]; order.push(u); for(const v of adj[u]) if(--indeg[v]===0) q.push(v); }
  return order;
}

function kmpSearch(text, pat){
  const n=text.length, m=pat.length; if(!m) return [];
  const lps=Array(m).fill(0);
  for(let i=1,len=0;i<m;){ if(pat[i]===pat[len]) lps[i++]=++len; else if(len) len=lps[len-1]; else lps[i++]=0; }
  const res=[];
  for(let i=0,j=0;i<n;){ if(text[i]===pat[j]){ i++; j++; if(j===m){ res.push(i-m); j=lps[j-1]; } } else if(j) j=lps[j-1]; else i++; }
  return res;
}

function rabinKarp(text, pat){
  const n=text.length, m=pat.length; if(!m || m>n) return [];
  const B=131n, MOD=1000000007n;
  let powB=1n; for(let i=0;i<m-1;i++) powB = (powB*B)%MOD;
  let hpat=0n, hwin=0n;
  for(let i=0;i<m;i++){ hpat=(hpat*B+BigInt(pat.charCodeAt(i)))%MOD; hwin=(hwin*B+BigInt(text.charCodeAt(i)))%MOD; }
  const out=[];
  for(let i=0;i<=n-m;i++){
    if(hpat===hwin && text.slice(i,i+m)===pat) out.push(i);
    if(i<n-m){
      hwin = ( (hwin - BigInt(text.charCodeAt(i))*powB)%MOD + MOD )%MOD;
      hwin = (hwin*B + BigInt(text.charCodeAt(i+m)))%MOD;
    }
  }
  return out;
}

function sieveIsPrime(n){
  const is = Array(n+1).fill(1); if(n>=0) is[0]=0; if(n>=1) is[1]=0;
  for(let p=2; p*p<=n; p++) if(is[p]) for(let x=p*p; x<=n; x+=p) is[x]=0;
  return is;
}

function editDistance(a,b){
  const m=a.length, n=b.length;
  let prev=Array(n+1).fill(0), cur=Array(n+1).fill(0);
  for(let j=0;j<=n;j++) prev[j]=j;
  for(let i=1;i<=m;i++){
    cur[0]=i; const ai=a.charCodeAt(i-1);
    for(let j=1;j<=n;j++){
      const cost = (ai===b.charCodeAt(j-1))?0:1;
      const del=prev[j]+1, ins=cur[j-1]+1, rep=prev[j-1]+cost;
      cur[j]=Math.min(del,ins,rep);
    }
    [prev,cur]=[cur,prev];
  }
  return prev[n];
}

function lisLength(a){
  const tails=[];
  for(const x of a){
    let i=lowerBound(tails,x);
    tails[i]=x;
  }
  return tails.length;
}
function lowerBound(arr,x){
  let l=0,r=arr.length;
  while(l<r){ const m=(l+r)>>1; if(arr[m]>=x) r=m; else l=m+1; }
  return l;
}

function quickselect(a, k){ // k: 1-based
  let l=0, r=a.length-1; k--;
  while(l<=r){
    const pivot=a[r]; let i=l;
    for(let j=l;j<r;j++) if(a[j]<=pivot){ [a[i],a[j]]=[a[j],a[i]]; i++; }
    [a[i],a[r]]=[a[r],a[i]];
    if(i===k) return a[i]; else if(i>k) r=i-1; else l=i+1;
  }
  throw new Error('k out of range');
}

class MinHeap {
  constructor(){ this.h = []; }
  size(){ return this.h.length; }
  peek(){ return this.h.length ? this.h[0] : null; }
  push(x){ const h=this.h; h.push(x); let i=h.length-1; while(i>0){ const p=(i-1)>>1; if(h[p] <= h[i]) break; [h[p],h[i]]=[h[i],h[p]]; i=p; } }
  pop(){ const h=this.h; if(!h.length) return null; const top=h[0]; const x=h.pop(); if(h.length){ h[0]=x; let i=0; for(;;){ const l=i*2+1, r=l+1; let s=i; if(l<h.length && h[l]<h[s]) s=l; if(r<h.length && h[r]<h[s]) s=r; if(s===i) break; [h[i],h[s]]=[h[s],h[i]]; i=s; } } return top; }
}

class DSU {
  constructor(n){ this.p=Array.from({length:n},(_,i)=>i); this.r=Array(n).fill(0); }
  find(x){ return this.p[x]===x ? x : (this.p[x]=this.find(this.p[x])); }
  unite(a,b){ a=this.find(a); b=this.find(b); if(a===b) return false; if(this.r[a]<this.r[b]) [a,b]=[b,a]; this.p[b]=a; if(this.r[a]===this.r[b]) this.r[a]++; return true; }
}

function threeSum(nums){
  nums = nums.slice().sort((a,b)=>a-b);
  const res=[]; const n=nums.length;
  for(let i=0;i<n;i++){
    if(i>0 && nums[i]===nums[i-1]) continue;
    let l=i+1, r=n-1; const target=-nums[i];
    while(l<r){
      const s = nums[l]+nums[r];
      if(s===target){
        res.push([nums[i], nums[l], nums[r]]);
        l++; r--;
        while(l<r && nums[l]===nums[l-1]) l++;
        while(l<r && nums[r]===nums[r+1]) r--;
      }else if(s<target) l++; else r--;
    }
  }
  return res;
}

function nextGreaterElementsCircular(nums){
  const n=nums.length, res=Array(n).fill(-1), st=[];
  for(let i=0;i<2*n;i++){
    const idx=i%n;
    while(st.length && nums[st[st.length-1]] < nums[idx]){ res[st.pop()] = nums[idx]; }
    if(i<n) st.push(idx);
  }
  return res;
}

class TrieNode {
  constructor(){ this.children=Object.create(null); this.end=false; }
}
class Trie {
  constructor(){ this.root=new TrieNode(); }
  insert(word){ let cur=this.root; for(const ch of word){ if(!cur.children[ch]) cur.children[ch]=new TrieNode(); cur=cur.children[ch]; } cur.end=true; }
  search(word){ let cur=this.root; for(const ch of word){ if(!cur.children[ch]) return false; cur=cur.children[ch]; } return cur.end===true; }
  startsWith(prefix){ let cur=this.root; for(const ch of prefix){ if(!cur.children[ch]) return false; cur=cur.children[ch]; } return true; }
}

function minWindow(s, t){
  if(!t) return '';
  const need=new Map();
  for(const c of t) need.set(c, (need.get(c)||0)+1);
  let needCnt=t.length, l=0, res='';
  for(let r=0;r<s.length;r++){
    const c=s[r];
    if(need.has(c)){ if(need.get(c)>0) needCnt--; need.set(c, need.get(c)-1); }
    while(needCnt===0){
      const cand=s.slice(l, r+1);
      if(!res || cand.length<res.length) res=cand;
      const c2=s[l++];
      if(need.has(c2)){ need.set(c2, need.get(c2)+1); if(need.get(c2)>0) needCnt++; }
    }
  }
  return res;
}

function mergeIntervals(intervals){
  if(intervals.length===0) return [];
  intervals = intervals.slice().sort((a,b)=>a[0]-b[0]);
  const res=[intervals[0].slice()];
  for(let i=1;i<intervals.length;i++){
    const last=res[res.length-1];
    if(intervals[i][0] <= last[1]) last[1] = Math.max(last[1], intervals[i][1]);
    else res.push(intervals[i].slice());
  }
  return res;
}

class SegTree {
  constructor(arr){
    const n0 = arr.length; this.n=1; while(this.n<n0) this.n<<=1;
    this.t = new Array(this.n*2).fill(0);
    for(let i=0;i<n0;i++) this.t[this.n+i]=arr[i];
    for(let i=this.n-1;i>0;i--) this.t[i]=this.t[i<<1]+this.t[i<<1|1];
  }
  pointUpdate(i, val){ let p=this.n+i; this.t[p]=val; for(p>>=1;p>0;p>>=1) this.t[p]=this.t[p<<1]+this.t[p<<1|1]; }
  rangeSum(l, r){ l+=this.n; r+=this.n; let res=0; while(l<=r){ if((l&1)===1) res+=this.t[l++]; if((r&1)===0) res+=this.t[r--]; l>>=1; r>>=1; } return res; }
}

function shuffleArray(arr) {
    const result = arr.slice();
    for (let i = result.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [result[i], result[j]] = [result[j], result[i]];
    }
    return result;
}

function shallowCopy(obj) {
    return Object.assign({}, obj);
}

function groupBy(arr, keyOrFn) {
    return arr.reduce((groups, item) => {
        const key = typeof keyOrFn === 'function' ? keyOrFn(item) : item[keyOrFn];
        groups[key] = groups[key] || [];
        groups[key].push(item);
        return groups;
    }, {});
}

function withTimeout(promise, ms) {
    return Promise.race([
        promise,
        new Promise((_, reject) => 
            setTimeout(() => reject(new Error('Timeout')), ms)
        )
    ]);
}

function curry(fn) {
    return function curried(...args) {
        if (args.length >= fn.length) {
            return fn.apply(this, args);
        } else {
            return (...args2) => curried(...args, ...args2);
        }
    };
}

function mapRange(value, inMin, inMax, outMin, outMax) {
    return (value - inMin) * (outMax - outMin) / (inMax - inMin) + outMin;
}

function deleteCookie(name, path = '/') {
    document.cookie = `${encodeURIComponent(name)}=;expires=Thu, 01 Jan 1970 00:00:00 GMT;path=${path}`;
}

function downloadFile(content, filename, type = 'text/plain') {
    const blob = content instanceof Blob ? content : new Blob([content], { type });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = filename;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
}
